param([Parameter(Mandatory=$true)][ValidateSet('Additional','Symmetric')][string]$VariationMode,[string]$Source='')
$ErrorActionPreference='Stop'
$root=Split-Path $PSScriptRoot
if(!$Source){$Source=Join-Path $root 'MVP.txt'}
$reference=Get-Content "$root/src/RagnarokCompanion/Data/mvp-respawns.json" -Raw -Encoding UTF8|ConvertFrom-Json
$ids=@{};foreach($record in $reference.Records){$ids[$record.MonsterName]=$record.MonsterId}
$aliases=@{'Garm'=1252;'Fallen Bishop'=1871;'Nightmare Amon Ra'=2362;'Memória de Thanatos'=1708;'Beelzebub'=1874;'Bone Detardeurus'=20618;'Rigid Muspellskoll'=20419;'Corrupted Spider Queen'=20421;'Corrupted Dark Lord'=20422;'Jungoliant'=20601;'Valkyrie Reginleif'=20610;'Valkyrie Ingrid'=20611}
foreach($key in $aliases.Keys){$ids[$key]=$aliases[$key]}
function Seconds([string]$value){if($value.Trim() -eq '-'){return 0};$matches=[regex]::Matches($value,'(\d+)\s*(h|min|s)');if(!$matches.Count -or [regex]::Replace($value,'(\d+)\s*(h|min|s)','').Trim()){throw "Duração inválida: $value"};$seconds=0;foreach($m in $matches){$seconds+=[int]$m.Groups[1].Value*$(switch($m.Groups[2].Value){'h'{3600};'min'{60};'s'{1}})};return $seconds}
$records=@();foreach($line in Get-Content $Source -Encoding UTF8){$parts=$line.Split('|');if($parts.Count -ne 4 -or ($parts[0].Trim() -eq 'MVP' -or $parts[0].Trim() -match '^-+$')){continue};$name=$parts[0].Trim();$map=$parts[1].Trim();if(!$ids.ContainsKey($name)){throw "ID não identificado: $name"};if($map -notmatch '^[a-z0-9_]+$'){throw 'Código de mapa inválido.'};$base=Seconds $parts[2];$variation=Seconds $parts[3];$minimum=if($VariationMode -eq 'Symmetric'){$base-$variation}else{$base};if($minimum -le 0){throw 'Janela inválida.'};$records+= [ordered]@{MonsterId=$ids[$name];MonsterName=$name;MapCode=$map;SpawnIdentifier='farmland-world';ScheduleType='Interval';RespawnBaseSeconds=$base;RespawnVarianceSeconds=$variation;RespawnMinSeconds=$minimum;RespawnMaxSeconds=($base+$variation);VariationMode=$VariationMode;Source='Farmland — dados fornecidos pelo ADM';SourceVersion='farmland-mvp-2026-10-20';SourceUrl='';IsFarmlandConfirmed=$true;LastVerifiedAt='2026-10-20T00:00:00-03:00'}}
if($records.Count -ne 55){throw "Esperados 55 pontos de spawn; encontrados $($records.Count)."}
$document=[ordered]@{Version=1;VariationMode=$VariationMode;Records=$records};$output=Join-Path $root 'src/RagnarokCompanion/Data/farmland-mvp-respawns.json';[IO.File]::WriteAllText($output,($document|ConvertTo-Json -Depth 8),(New-Object Text.UTF8Encoding($false)));Write-Output "$($records.Count) pontos importados; variação $VariationMode."
